@startuml

class Customer {
  + Name : string
  + Surname : string
  + Email : string
  + Telephone : string
  + HomeAddress : string
}

class Order {
  + TotalCost : double
  + EstimatedDeliveryTime : datetime
  + Status : string
}

class Dish {
  + Name : string
  + PreparationTime : int
}

class Payment {
  + PaymentMethod : string
  + Status : string
}

class Kitchen {
  + CurrentWorkload : int
}

class Delivery {
  + Status : string
}

Customer "1" -- "*" Order : places
Order "1" *-- "1..*" Dish : contains
Order "1" -- "1" Payment : paid by
Order "1" -- "1" Kitchen : sent to
Order "1" -- "1" Delivery : handled by

@enduml

